CREATE TYPE "CommunicationChannel" AS ENUM ('EMAIL','WHATSAPP','SMS');
CREATE TYPE "CommunicationStatus" AS ENUM ('DRAFT','QUEUED','SENDING','SENT','DELIVERED','READ','FAILED','SUPPRESSED');
CREATE TYPE "RefundCaseStatus" AS ENUM ('REQUESTED','UNDER_REVIEW','APPROVED','REJECTED','PROCESSING','COMPLETED','FAILED');
CREATE TABLE "CommunicationTemplate" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "channel" "CommunicationChannel" NOT NULL, "subject" TEXT, "body" TEXT NOT NULL, "providerTemplateId" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CommunicationTemplate_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CommunicationTemplate_name_key" ON "CommunicationTemplate"("name");
CREATE TABLE "CommunicationConsent" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "channel" "CommunicationChannel" NOT NULL, "marketingAllowed" BOOLEAN NOT NULL DEFAULT false, "transactionalAllowed" BOOLEAN NOT NULL DEFAULT true, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CommunicationConsent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CommunicationConsent_userId_channel_key" ON "CommunicationConsent"("userId","channel");
CREATE TABLE "CommunicationDelivery" ("id" TEXT NOT NULL, "templateId" TEXT, "userId" TEXT, "channel" "CommunicationChannel" NOT NULL, "recipient" TEXT NOT NULL, "subject" TEXT, "body" TEXT NOT NULL, "status" "CommunicationStatus" NOT NULL DEFAULT 'DRAFT', "attempts" INTEGER NOT NULL DEFAULT 0, "providerMessageId" TEXT, "lastError" TEXT, "nextRetryAt" TIMESTAMP(3), "deliveredAt" TIMESTAMP(3), "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CommunicationDelivery_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CommunicationDelivery_status_nextRetryAt_idx" ON "CommunicationDelivery"("status","nextRetryAt");
CREATE TABLE "RefundCase" ("id" TEXT NOT NULL, "paymentId" TEXT NOT NULL, "requestedAmount" DECIMAL(12,2) NOT NULL, "reason" TEXT NOT NULL, "status" "RefundCaseStatus" NOT NULL DEFAULT 'REQUESTED', "providerReference" TEXT, "reviewerId" TEXT, "reviewNotes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "RefundCase_pkey" PRIMARY KEY ("id"));
CREATE INDEX "RefundCase_paymentId_status_idx" ON "RefundCase"("paymentId","status");
